"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[10849],{3331:(e,r,n)=>{n.d(r,{R:()=>a,x:()=>o});var t=n(36672);const i={},s=t.createContext(i);function a(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(s.Provider,{value:r},e.children)}},64679:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>d,contentTitle:()=>o,default:()=>k,frontMatter:()=>a,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"Opbygning af GitHub med Ruby on Rails","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/da/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8. april 2023","top_news":"Opbygning af GitHub med Ruby on Rails"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/da/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/da/2023/04/07"}}');var i=n(23420),s=n(3331);const a={localized_date:"8. april 2023",top_news:"Opbygning af GitHub med Ruby on Rails"},o="2023-04-08",d={},l=[{value:"Opbygning af GitHub med Ruby on Rails",id:"opbygning-af-github-med-ruby-on-rails",level:2},{value:"Sp\xf8rg Wirecutter: Kan du anbefale et ikke-smart tv til mig?",id:"sp\xf8rg-wirecutter-kan-du-anbefale-et-ikke-smart-tv-til-mig",level:2},{value:"Codeberg - Hurtigt open source-alternativ til GitHub",id:"codeberg---hurtigt-open-source-alternativ-til-github",level:2},{value:"Fler\xe5rige ris: Plant \xe9n gang, h\xf8st igen og igen",id:"fler\xe5rige-ris-plant-\xe9n-gang-h\xf8st-igen-og-igen",level:2},{value:"60 mio. amerikanere har skatter, der er s\xe5 enkle, at skattev\xe6senet kunne lave dem automatisk",id:"60-mio-amerikanere-har-skatter-der-er-s\xe5-enkle-at-skattev\xe6senet-kunne-lave-dem-automatisk",level:2},{value:"Vi skal fort\xe6lle folk, at ChatGPT vil lyve for dem, ikke debattere lingvistik",id:"vi-skal-fort\xe6lle-folk-at-chatgpt-vil-lyve-for-dem-ikke-debattere-lingvistik",level:2},{value:"Twitter tillader ikke retweetning af tweets, der linker til Substack",id:"twitter-tillader-ikke-retweetning-af-tweets-der-linker-til-substack",level:2},{value:"Western Digital cloud-tjenester nede i 4 dage",id:"western-digital-cloud-tjenester-nede-i-4-dage",level:2},{value:"Hvordan fungerer database-sharding?",id:"hvordan-fungerer-database-sharding",level:2},{value:"Hubble ser muligt l\xf8bsk sort hul, der skaber et spor af stjerner",id:"hubble-ser-muligt-l\xf8bsk-sort-hul-der-skaber-et-spor-af-stjerner",level:2},{value:"NZ&#39;s st\xf8rste databrud viser, at retention er den sovende gigant inden for datasikkerhed",id:"nzs-st\xf8rste-databrud-viser-at-retention-er-den-sovende-gigant-inden-for-datasikkerhed",level:2},{value:"USA og Kina f\xf8rer krig under b\xf8lgerne om internetkabler",id:"usa-og-kina-f\xf8rer-krig-under-b\xf8lgerne-om-internetkabler",level:2},{value:"Database &quot;sharding&quot; kom fra Ultima Online?",id:"database-sharding-kom-fra-ultima-online",level:2},{value:"Hvorfor har Phreesia delt mine medicinske data, efter at jeg har fravalgt dem?",id:"hvorfor-har-phreesia-delt-mine-medicinske-data-efter-at-jeg-har-fravalgt-dem",level:2},{value:"JavaScript-algoritmer: Algoritmer og datastrukturer implementeret i JavaScript",id:"javascript-algoritmer-algoritmer-og-datastrukturer-implementeret-i-javascript",level:2},{value:"SpaceX n\xe6rmer sig den f\xf8rste opsendelse af Starship Super Heavy",id:"spacex-n\xe6rmer-sig-den-f\xf8rste-opsendelse-af-starship-super-heavy",level:2},{value:"Opbygning af musikalske synthesizere med SQL-foresp\xf8rgsler",id:"opbygning-af-musikalske-synthesizere-med-sql-foresp\xf8rgsler",level:2},{value:"Den l\xe6ngste lige linje i Storbritannien uden at krydse en offentlig vej",id:"den-l\xe6ngste-lige-linje-i-storbritannien-uden-at-krydse-en-offentlig-vej",level:2},{value:"Flipper Zero forbudt af Amazon for at v\xe6re en &quot;card skimming device",id:"flipper-zero-forbudt-af-amazon-for-at-v\xe6re-en-card-skimming-device",level:2},{value:"Reverse Engineering af Facebook Messenger API&#39;et",id:"reverse-engineering-af-facebook-messenger-apiet",level:2},{value:"Tatjana van Varks maskiner",id:"tatjana-van-varks-maskiner",level:2},{value:"Big Ball of Mud (1999)",id:"big-ball-of-mud-1999",level:2},{value:"Yann LeCun og Andrew Ng: Why the 6-Month AI Pause Is a Bad Idea [video]",id:"yann-lecun-og-andrew-ng-why-the-6-month-ai-pause-is-a-bad-idea-video",level:2},{value:"NSA oprettede online cybersikkerhedskursus med 100-vis af klasser",id:"nsa-oprettede-online-cybersikkerhedskursus-med-100-vis-af-klasser",level:2},{value:"Erstatning af d\xe5rlige systemer med d\xe5rlige systemer",id:"erstatning-af-d\xe5rlige-systemer-med-d\xe5rlige-systemer",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Sp\xf8rg Hvad er din bedste ressource til at holde dig ajour med udviklingen inden for AI?",id:"sp\xf8rg-hvad-er-din-bedste-ressource-til-at-holde-dig-ajour-med-udviklingen-inden-for-ai",level:2},{value:"Direkte beviser for brugen af flere stoffer i bronzealderen fra test af menneskeh\xe5r",id:"direkte-beviser-for-brugen-af-flere-stoffer-i-bronzealderen-fra-test-af-menneskeh\xe5r",level:2},{value:"NYPD-officerer praler med at malke overtid i utilsigtet optagelse",id:"nypd-officerer-praler-med-at-malke-overtid-i-utilsigtet-optagelse",level:2},{value:"Vis ChatGDB - GPT-drevet GDB-assistent",id:"vis-chatgdb---gpt-drevet-gdb-assistent",level:2}];function g(e){const r={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,i.jsx)(r.h2,{id:"opbygning-af-github-med-ruby-on-rails",children:"Opbygning af GitHub med Ruby on Rails"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Original"}),".\nGitHub.com er skrevet med Ruby on Rails og vedligeholdes af over tusind ingeni\xf8rer med n\xe6sten 2 millioner linjer kode. Virksomheden opgraderer ugentligt til den seneste Rails commit med pull requests og revisionsgennemgange. Fordelene ved disse opgraderinger er bl.a. bedre h\xe5ndtering af databaseforbindelser og hurtigere visningsgengivelse, forbedret sikkerhed og lavere risiko for ukendte problemer. Test af de nyeste versioner identificerer og l\xf8ser problemer inden frigivelse. Indl\xe6gget er en GitHub Privacy Statement, der indeholder oplysninger om produktfunktioner, sikkerhed, historier, prisfasts\xe6ttelse, ressourcer, udvikler-API, partnere, platform og support. Indl\xe6gget ser ikke ud til at indeholde nye oplysninger eller begivenheder, og det er uklart, hvorfor det f\xe5r opm\xe6rksomhed."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub har ombygget sin platform med Ruby on Rails, hvilket har vakt interesse for den potentielle indvirkning p\xe5 Rails-\xf8kosystemet & kravene til testd\xe6kning. Brugere fremh\xe6ver udfordringer ved at mestre Ruby, s\xe5som ekstrem testd\xe6kning & potentiale for fremtidige kodefejl. Nogle brugere foresl\xe5r at bruge Sorbet til st\xe6rkere kontroltyper. GitHubs brug af Crystal-sproget og Rubys metaprogrammeringspotentiale roses, mens nogle kritiserer Rubys datavidenskabsrum. Microsofts nylige opgradering af Githubs Rails-platform fra version 2.3 til 3 gav udfordringer, men statisk typing hj\xe6lper opgraderinger. Udviklere reflekterer over kompromiserne mellem teknologiske tendenser og etableret stabilitet, hvor nogle bem\xe6rker Rails' brugervenlighed, men det bagudrettede visningslag. Opgraderinger af rammen sker mest effektivt gradvist, med gode testmuligheder p\xe5 plads. Mange organisationer anser det for vigtigt at opdatere it-infrastruktur, GitHubs testmuligheder roses, og Sorbet bruges af GitHub til Ruby og Rails."]}),"\n",(0,i.jsx)(r.h2,{id:"sp\xf8rg-wirecutter-kan-du-anbefale-et-ikke-smart-tv-til-mig",children:"Sp\xf8rg Wirecutter: Kan du anbefale et ikke-smart tv til mig?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"Original"}),".\nWirecutter foresl\xe5r at sikre smarte tv'er i stedet for at finde ikke-smarte muligheder p\xe5 grund af hensyn til privatlivets fred. Frakoblede tv'er kan mangle nyttige funktioner. Eksperter r\xe5der til at frav\xe6lge dataindsamling, kun tilslutte til Wi-Fi til firmwareopdateringer og lejlighedsvis streaming for at frav\xe6lge. Gamle tv'er, 4K-sk\xe6rme eller projektorer er alternativer. Lignende problemer med beskyttelse af privatlivets fred g\xf8r sig g\xe6ldende for andre internetforbundne enheder."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nI en artikel diskuteres det vanskelige i at finde et ikke-smart tv uden p\xe5tr\xe6ngende og un\xf8dvendige funktioner. Forslag til l\xf8sninger omfatter brug af et frakoblet smart-tv eller fysisk frakobling af moduler for at forhindre u\xf8nskede forbindelser. Der er bekymringer om privatlivets fred og dataudtr\xe6ngning. Diskussion om energiforbrug, potentielle automatiske tilslutninger og brugernes langsomme opstart af smart-tv'er. Forslag til et potentielt navn til et ikke-smart tv og ideelle smart-tv-funktioner. Bekymring for datasporing og vanskelighederne ved at starte en virksomhed med dumme sk\xe6rme af h\xf8j kvalitet. Brugere diskuterer specifikke sk\xe6rmfunktioner og vanskelighederne ved at holde smart-tv'er frakoblet. TCL's uetiske adf\xe6rd og brugernes bekymringer om privatlivets fred fremh\xe6ves."]}),"\n",(0,i.jsx)(r.h2,{id:"codeberg---hurtigt-open-source-alternativ-til-github",children:"Codeberg - Hurtigt open source-alternativ til GitHub"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://codeberg.org/",children:"Original"}),".\nCodeberg.org er en gratis og open source-softwaresamarbejdsplatform og Git-hosting, der drives af brugerne via en nonprofitorganisation i Berlin. Platformen fremmer ogs\xe5 et f\xe6llesskab af ligesindede fri software- og indholdsskabere uden sporing eller salg af brugerdata. Brugerne kan registrere og hoste deres projekter p\xe5 webstedet, og Codeberg e.V. opretholder f\xe6llesskabet gennem donationer og frivillige bidrag. Webstedet er tilg\xe6ngeligt p\xe5 flere sprog, og brugerne kan tilbyde bidrag til at forbedre de tjenester, der ligger bag Codeberg."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg er et hurtigt open source-alternativ til Github, der fokuserer p\xe5 samarbejde om gratis og open source-software. Discussion Service-brugere diskuterer, om Codebergs fokus p\xe5 open source-etik er for restriktivt, mens andre roser Codeberg for sit engagement. I forbindelse med diskussionen om it-infrastrukturens politiske karakter h\xe6vder nogle, at neutralitet er umulig, men at man stadig b\xf8r str\xe6be efter neutralitet, mens andre h\xe6vder, at politiske holdninger er mere tolerable inden for it end i andre sammenh\xe6nge. Discussion Service-brugere diskuterer ogs\xe5 filosofien om kodedeling, restriktive licenser og virksomhedsvenlige koders indvirkning p\xe5 FOSS-succesraten. Codebergs non-profit-status og engagement i licenser for fri software roses. Platformens hurtige hastighed og enkle gr\xe6nseflade er v\xe6rdsat, men der er bekymringer om privatlivets fred. Nogle anbefaler Radicle som et alternativ til centraliserede tjenester som Github."]}),"\n",(0,i.jsx)(r.h2,{id:"fler\xe5rige-ris-plant-\xe9n-gang-h\xf8st-igen-og-igen",children:"Fler\xe5rige ris: Plant \xe9n gang, h\xf8st igen og igen"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"Original"}),".\nForskere har skabt fler\xe5rige risstammer, der forbliver produktive og vokser igen efter hver h\xf8st, hvilket giver store milj\xf8m\xe6ssige fordele, et lavere CO2-fodaftryk, en sundere jordbund og landm\xe6nd, der ikke beh\xf8ver at s\xe5 igen. Disse stammer, der er blevet fremavlet i l\xf8bet af de sidste to \xe5rtier, er blevet testet og h\xf8stet fire \xe5r i tr\xe6k af 45.000 sm\xe5 landbrugere, der lever af selvforsyning. Eksperter forudser, at hvis flere landm\xe6nd anvender de nye sorter, kan fordelene blive store for de mennesker, der dyrker dem, milj\xf8et og verdens befolkning, der er afh\xe6ngige af ris som basisf\xf8devare."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nFler\xe5rige ris kan reducere metanudledningen fra rismarker. Husdyrproduktion har en betydelig indvirkning p\xe5 milj\xf8et. Klima\xe6ndringer vil f\xf8re til f\xf8devaremangel og andre problemer. Metan fra rismarker har ikke en v\xe6sentlig indvirkning sammenlignet med andre kilder. Fler\xe5rige ris har potentielle fordele, men ogs\xe5 udfordringer. Eksperter dr\xf8fter landbrug og f\xf8devareproduktion. Der redeg\xf8res for succesen med vandede fler\xe5rige ris. Fler\xe5rige afgr\xf8der kan spare p\xe5 arbejdskraft og inputomkostninger. Fler\xe5rige planter har fordele for jordbunden og udvinding af n\xe6ringsstoffer."]}),"\n",(0,i.jsx)(r.h2,{id:"60-mio-amerikanere-har-skatter-der-er-s\xe5-enkle-at-skattev\xe6senet-kunne-lave-dem-automatisk",children:"60 mio. amerikanere har skatter, der er s\xe5 enkle, at skattev\xe6senet kunne lave dem automatisk"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"Original"}),'.\nMindst 41 % af de amerikanske husstande, eller 62 millioner skatteans\xf8gningsenheder, kunne f\xe5 hele deres selvangivelse h\xe5ndteret af skattev\xe6senet via "pr\xe6udfyldte selvangivelser" uden yderligere indgreb. Den mindre konservative tilgang ansl\xe5r tallet til 73 mio. selvangivelser eller 48 %. Muligheden for automatiske selvangivelser kan spare tid og angst hvert \xe5r og g\xf8re skattes\xe6sonen mere effektiv. Artiklen forts\xe6tter med kort at d\xe6kke andre emner, der ikke har noget med skat at g\xf8re, s\xe5som den katolske kirkes krise i forbindelse med seksuelt misbrug af b\xf8rn og Teslas kameraer, der er under kontrol. Den fremh\xe6ver dog prim\xe6rt unikke l\xf8sninger p\xe5 v\xe6sentlige problemer, som er d\xe6kket i Future Perfect-nyhedsbrevet. Artiklen forbliver neutral og informativ, uden nogen politisk eller religi\xf8s bias.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\n60 mio. amerikaneres skat er enkel nok til, at IRS automatisk beregner den. Den letteste m\xe5de for IRS at tjene penge p\xe5 er at revidere \xf8konomisk s\xe5rbare personer. Intuit bidrager til f\xe6nomenet med uigennemsigtige love. IRS' h\xe5ndh\xe6velse er begr\xe6nset, s\xe5 amerikanere med lav indkomst bliver revideret mere. De seneste skatte\xe6ndringer betyder f\xe6rre muligheder for specificerede fradrag. IRS kan ikke maksimere sin automatiske skatteevne. IRS' budget er faldet, men er for nylig blevet forh\xf8jet; nogle mener, at de ekstra midler vil g\xf8re det muligt for IRS at maksimere indt\xe6gterne i stedet for at m\xe5lrette sig mod bestemte personer. Forslag om at beskatte p\xe5 grundlag af X-sats, indgive ans\xf8gning, hvis man er uenig. Forudfyldte selvangivelser ville spare tid og penge, men er ikke idiotsikre. Virksomhedslobbyisme bidrager til det nuv\xe6rende selvbetjeningsskattesystems kompleksitet. Det er ikke muligt at automatisere fradrag for salgsmoms ved kontanttransaktioner. Skatteforberedelse spilder milliarder af dollars og tid."]}),"\n",(0,i.jsx)(r.h2,{id:"vi-skal-fort\xe6lle-folk-at-chatgpt-vil-lyve-for-dem-ikke-debattere-lingvistik",children:"Vi skal fort\xe6lle folk, at ChatGPT vil lyve for dem, ikke debattere lingvistik"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"Original"}),".\nArtiklen diskuterer problemerne omkring store sprogmodeller (LLM'er) som ChatGPT, der kan lyve over for folk og have fejl, som ikke kan rettes. Forfatteren h\xe6vder, at det er vigtigere at advare folk om risiciene ved at bruge LLM'er end at debattere lingvistik. Selv om LLM'er kan v\xe6re nyttige, er de ikke f\xf8lende og kan ikke stole p\xe5, at de kan give faktuelle oplysninger. Artiklen rejser etiske sp\xf8rgsm\xe5l om, hvorvidt vi b\xf8r tilskynde folk til at bruge LLM'er p\xe5 trods af deres fejl eller ej. Forfatteren konkluderer, at det er vigtigt at n\xe6rme sig LLM'er med forsigtighed, og understreger behovet for at advare folk om, at ChatGPT kan lyve."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT kan vildlede brugerne og skal gentagne gange fort\xe6lles, at man ikke skal stole p\xe5 det. Dens anvendelighed kan v\xe6re begr\xe6nset, hvis tendensen til at hallucinere ikke bliver l\xf8st. ChatGPT mangler r\xe6sonnementsevner og kan generere falske oplysninger. Nogle er begejstrede for dens potentielle fremskridt, men nogle kritiserer den for dens manglende evne til at abstrahere eller r\xe6sonnere. AI-genereret tekst kr\xe6ver skepsis og b\xf8r ses som en assistent, der er velbel\xe6st, men potentielt tilb\xf8jelig til at konflikte. ChatGPT er dog nyttig til at generere kodeeksempler og besvare komplekse foresp\xf8rgsler. Den giver pr\xe6cise svar i op til 99 % af tilf\xe6ldene. Brugerne skal forst\xe5 dens begr\xe6nsninger for at undg\xe5 at tildele ChatGPT mere moralitet end n\xf8dvendigt."]}),"\n",(0,i.jsx)(r.h2,{id:"twitter-tillader-ikke-retweetning-af-tweets-der-linker-til-substack",children:"Twitter tillader ikke retweetning af tweets, der linker til Substack"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"Original"}),".\nTwitter er begyndt at begr\xe6nse tweets med links til Substack.com som reaktion p\xe5 Substacks annoncering af et nyt produkt, Notes, som vil v\xe6re en direkte konkurrent til Twitter. Brugerne har bem\xe6rket, at de ikke kan retweete eller besvare tweets med Substack-links, og Twitter er tilsyneladende begyndt at blokere for tweet-embedding i Substack-indl\xe6g. Denne begr\xe6nsning menes at v\xe6re et fors\xf8g fra Twitters side p\xe5 at begr\xe6nse en konkurrents r\xe6kkevidde p\xe5 deres platform. Twitter begyndte p\xe5 samme m\xe5de at blokere links til konkurrerende sociale medieplatforme i december 2022. Substack har endnu ikke svaret p\xe5 sp\xf8rgsm\xe5l om denne sag."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter forb\xf8d retweets af tweets, der linker til Substack, idet det at synes godt om s\xe5danne indl\xe6g undertrykker diskussionen. Dette skridt har udl\xf8st kritik af ytringsfriheden, Elon Musks holdning til den og Substacks konkurrence. Mastodon ses som en erstatning for Twitter for nogle. Diskussioner om PR, afh\xe6ngighed af sociale medier og tvivlsom praksis er omfattet. Der n\xe6vnes ingen ny teknologi eller udgivelse."]}),"\n",(0,i.jsx)(r.h2,{id:"western-digital-cloud-tjenester-nede-i-4-dage",children:"Western Digital cloud-tjenester nede i 4 dage"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://status.mycloud.com/os4",children:"Original"}),".\nWestern Digital oplevede et nedbrud, der startede den 2. april, og som p\xe5virkede tjenesterne My Cloud, My Cloud Home, SanDisk ibi og andre relaterede produkter, og en opdatering blev offentliggjort den 3. april. Nedbruddet fortsatte til den 7. april og p\xe5virkede adgangen til filer og programmer. Lokal adgang er tilg\xe6ngelig, s\xe5 brugerne kan f\xe5 adgang til deres personlige filer fra en Windows- eller MacOS-computer. Andre tidligere h\xe6ndelser omfatter intermitterende adgangsproblemer, intermitterende nulstilling af adgangskoder og intermitterende forbindelsesproblemer med cloud-tjenester. Visse brugere i Kina kan ogs\xe5 opleve adgangsproblemer."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nWestern Digitals cloud-tjenester har v\xe6ret nede i fire dage, og i kommentarer diskuteres afbrydelsen og virksomhedens garanti. Nogle brugere diskuterer begr\xe6nsningerne i GPT's sprogmodel og dens verdensmodel, og der stilles sp\xf8rgsm\xe5lstegn ved dens forst\xe5else af komplekse begreber. Kommentarerne unders\xf8ger ogs\xe5 juridiske termer omkring GPT's serviceansvar og garantier. Brugerne diskuterer v\xe6rdien af statussider under afbrydelser, og nogle foresl\xe5r alternative metoder som f.eks. chat. Brugerne diskuterer fordele og ulemper ved selvhosting, idet de \xf8nsker en fremtid, hvor der er adgang til folks medier fra alle steder. Western Digitals tidligere problemer med SMR-drev, der ikke blev markeret korrekt, har f\xe5et nogle brugere til at opfordre til en tilbagevenden til lokale l\xf8sninger."]}),"\n",(0,i.jsx)(r.h2,{id:"hvordan-fungerer-database-sharding",children:"Hvordan fungerer database-sharding?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"Original"}),'.\nArtiklen g\xe5r i dybden med database-sharding og forklarer fordelene ved at skalere ud i stedet for at skalere op med forskellige sharding-ordninger og -algoritmer, der diskuteres. Den d\xe6kker vigtige aspekter som f.eks. organisering af infrastruktur, oprettelse af routinglag og planl\xe6gning af migration, idet der l\xe6gges v\xe6gt p\xe5 betydningen af vedligeholdelse. Der gives en kort oversigt over sharding-rammer og v\xe6rkt\xf8jer som Vitess og Citus, og CockroachDB indleder \xe6raen med "serverl\xf8se" databaser. PlanetScale, en ny akt\xf8r p\xe5 markedet, tilbyder en shard-nativ database bygget p\xe5 MySQL og Vitess sammen med sine tekniske ressourcer.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nDebatter om fordele og udfordringer ved database-sharding; v\xe6lg et system, der matcher data; hot key throughput er et problem i auto-sharding; Spanner/Cockroach eller Dynamo/Cassandra-alternativer; CockroachDB tilbyder st\xe6rk konsistens og 2PC mellem shards; distributionskompleksitet kr\xe6ver betalte tjenester; fokus p\xe5 horisontal skalerbarhed for at undg\xe5 at investere i en enkelt maskine; godt n\xf8gledesign kan forhindre hotspots; sharding efter kunde er almindeligt; sharding af flere lejere foresl\xe5s for at opn\xe5 skalerbarhed; Yugabyte, Cockroach og TiDB n\xe6vnes; hashing af alle data til synkronisering er ikke skalerbart; svindlere udnytter Amazons praksis med kolocation af tabeller; MongoDB kr\xe6ver en supportkontrakt for virksomheder."]}),"\n",(0,i.jsx)(r.h2,{id:"hubble-ser-muligt-l\xf8bsk-sort-hul-der-skaber-et-spor-af-stjerner",children:"Hubble ser muligt l\xf8bsk sort hul, der skaber et spor af stjerner"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Original"}),".\nKan ikke generere et resum\xe9, da teksten er en fejlmeddelelse, der angiver, at anmodningen ikke kunne im\xf8dekommes p\xe5 grund af en konfigurationsfejl eller for meget trafik. Hvis du kontakter ejeren af appen eller webstedet eller gennemg\xe5r dokumentationen til CloudFront, kan det v\xe6re en hj\xe6lp til at fejlfinde og forhindre, at denne fejl opst\xe5r."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),'.\nHubble-teleskopet s\xe5 et sort hul, der efterlod et spor af stjerner, hvilket f\xf8rte til spekulationer om dets indvirkning p\xe5 liv og nye steder at finde beboelige planeter. Hubble fandt ogs\xe5 en sj\xe6lden galakse af Hoag-typen, der er ca. dobbelt s\xe5 stor som M\xe6lkevejen. Forskerne opdagede et sort hul, der skaber stjerner af gas, hvilket kan p\xe5virke universet og tiltr\xe6kke avancerede civilisationer. Et objekt, der bev\xe6ger sig meget hurtigt gennem rummet, skaber en supersonisk p\xe5virkning af gas, men brugen af "supersonisk" er sandsynligvis metaforisk. Discussion Service-brugere diskuterer scifi-historier som The Three-Body Problem og giver udtryk for forskellige meninger og anbefalinger af andre b\xf8ger i genren. Brugerne diskuterer ogs\xe5 sj\xe6ldenheden af jordlignende liv og det antropomorfe princip.']}),"\n",(0,i.jsx)(r.h2,{id:"nzs-st\xf8rste-databrud-viser-at-retention-er-den-sovende-gigant-inden-for-datasikkerhed",children:"NZ's st\xf8rste databrud viser, at retention er den sovende gigant inden for datasikkerhed"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"Original"}),".\nOver en million newzealandske k\xf8rekort og pas blev afsl\xf8ret i forbindelse med Latitude Financials databrud; nogle af oplysningerne var op til 18 \xe5r gamle. New Zealands stedfortr\xe6dende kommiss\xe6r for beskyttelse af privatlivets fred n\xe6vner datalagring som et kritisk problem i forbindelse med cybersikkerhedsangreb og fastsl\xe5r, at virksomheder og organisationer skal begr\xe6nse indsamling og lagring af data, som de ikke har brug for. Myndigheder b\xf8r udarbejde en tidsplan for opbevaring af personlige oplysninger, og enkeltpersoner b\xf8r sp\xf8rge de organisationer, de giver oplysninger til, hvorfor og hvordan de opbevares. Beskyttelse af privatlivets fred skal v\xe6re et afg\xf8rende forretningssp\xf8rgsm\xe5l med samme beskyttelse som sundhed og sikkerhed. Latitude Financial kontakter alle ber\xf8rte kunder for at underrette dem om bruddet og hj\xe6lpe med at l\xf8se problemet, samtidig med at vi samarbejder med tilsynsmyndighederne om at afd\xe6kke detaljerne i bruddet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nNZ's st\xf8rste databrud understreger behovet for ordentlige politikker for opbevaring af data; sletning b\xf8r prioriteres. GDPR har gjort fremskridt, men datalagring er fortsat udbredt. Discussion Service-brugere diskuterer ansvarlig dataindsamling, regeringsadgang og datasikkerhed. Metoder til sletning af data og \xe5rsagerne til opbevaring af data diskuteres. Personlige data skal minimeres og behandles som giftige aktiver. Virksomhederne har brug for bedre uddannelse om databeskyttelse."]}),"\n",(0,i.jsx)(r.h2,{id:"usa-og-kina-f\xf8rer-krig-under-b\xf8lgerne-om-internetkabler",children:"USA og Kina f\xf8rer krig under b\xf8lgerne om internetkabler"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"Original"}),".\nUSA og Kina er i kamp om unders\xf8iske kabler, der overf\xf8rer alt fra e-mails til milit\xe6re hemmeligheder. Den amerikanske regering har grebet ind i mindst seks private aftaler om unders\xf8iske kabler i de seneste fire \xe5r for at isolere Kinas h\xf8jteknologiske sektor og begr\xe6nse Kinas adgang til amerikansk teknologi. Det Hvide Hus tildelte for nylig kontrakten om kabler fra Singapore til Frankrig til det amerikanske SubCom i stedet for Kinas HMN Tech af sikkerhedshensyn. Den amerikanske regerings aggressive bestr\xe6belser p\xe5 at forhindre kinesisk spionage gennem s\xf8kabler forstyrrer teknologigiganternes planer og skaber uro i branchen. Kina tager til genm\xe6le ved at forsinke et kabelprojekt, der st\xf8ttes af Meta, nemlig Southeast Asia-Japan 2-kablet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),'.\nUSA og Kina konkurrerer om unders\xf8iske internetkabler, idet der er bekymring over nationale gr\xe6nser og censur. Forsinkelser og oml\xe6gninger af kabler har kostet teknologigigiganter millioner af kroner og \xf8rem\xe6rker. Eksperter anbefaler b\xf8ger om international infrastruktur. USA er bekymret over kinesisk spionage og deres evne til at indsamle og filtrere internettrafik. Kinas engagement i den alliancefrie bev\xe6gelse og B\xe6lte- og vejinitiativet rejser sp\xf8rgsm\xe5l. Mange "cybersikkerheds"-virksomheder mangler kvalificerede ingeni\xf8rer. CIA\'s torturprogram og ansvarlighed for krigsforbrydelser dr\xf8ftes.']}),"\n",(0,i.jsx)(r.h2,{id:"database-sharding-kom-fra-ultima-online",children:'Database "sharding" kom fra Ultima Online?'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Original"}),".\nBeklager, jeg kan ikke generere et resum\xe9 baseret p\xe5 denne tekst, da det er en fejlmeddelelse og ikke relateret til det givne emne."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nDiscussion Service-brugere diskuterer, hvordan "sharding" i databaser blev inspireret af Ultima Online. Personlige historier fort\xe6ller, hvordan UO f\xf8rte til at l\xe6re at kode. Plakater fort\xe6ller om UO\'s spilkarakteristika og dets indvirkning p\xe5 programmering.']}),"\n",(0,i.jsx)(r.h2,{id:"hvorfor-har-phreesia-delt-mine-medicinske-data-efter-at-jeg-har-fravalgt-dem",children:"Hvorfor har Phreesia delt mine medicinske data, efter at jeg har fravalgt dem?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"Original"}),".\nEn rapport fremh\xe6ver medicinalvirksomheder, der deler patientdata uden samtykke. Patienten n\xe6gtede at dele data, men fandt alligevel ud af, at hendes data blev delt af Phreesia. Forslag til en regel mod at presse patienten til at give sit samtykke. Behov for et standardtilvalg for at g\xf8re det klart og nemt at frav\xe6lge det. Den nuv\xe6rende proces er besv\xe6rlig. Ekspert foresl\xe5r, at ad-tech adskilles fra sundhedspleje. Forfatteren er etnografisk sociolog og dataforsker."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia delte medicinske data om patienter, der fravalgte det. Mange udtrykker bekymring over databeskyttelse og ansvarlighed og foresl\xe5r, at reklamer, der anvender f\xf8lsomme medicinske data, ikke b\xf8r v\xe6re lovligt tilladt. Der er behov for ordentlig dokumentation og rapportering for at holde s\xe5danne virksomheder ansvarlige for kr\xe6nkelser af privatlivets fred. Sundhedsudbydernes brug af elektroniske check-ins og m\xf8rke m\xf8nstre er blevet kritiseret. Der er behov for strenge love om samtykke og h\xe5ndh\xe6velse af dataindsamling i USA. Der s\xe6ttes ogs\xe5 sp\xf8rgsm\xe5lstegn ved sundhedsudbydernes profitmotiv og vrede over reglerne om patienters privatlivets fred."]}),"\n",(0,i.jsx)(r.h2,{id:"javascript-algoritmer-algoritmer-og-datastrukturer-implementeret-i-javascript",children:"JavaScript-algoritmer: Algoritmer og datastrukturer implementeret i JavaScript"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Original"}),".\nJavaScript-Algorithms er en omfattende samling af popul\xe6re algoritmer og datastrukturer implementeret i JavaScript, organiseret efter emne og paradigme. Det er velegnet til l\xe6rings- og forskningsform\xe5l og til produktionsbrug. Brugerne kan finde eksempler p\xe5 flere popul\xe6re algoritmer og datastrukturer, herunder krypterings-, evolution\xe6re og maskinl\xe6ringsalgoritmer. Opslaget indeholder forklaringer, Big O notation og links til yderligere l\xe6sning. Det indeholder ogs\xe5 en legeplads, hvor l\xe6serne kan eksperimentere med koden. Avancerede algoritmer som branch and bound og dynamisk programmering er inkluderet. L\xe6sere skal v\xe6re opm\xe6rksomme p\xe5, at donationer er velkomne, og at Node version 16 eller h\xf8jere er p\xe5kr\xe6vet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News kommenterer det popul\xe6re GitHub-repository 'JavaScript-algorithms'. Brugerne diskuterer sprogets egnethed til undervisning og praktisk brug, nogle advarer om uventet adf\xe6rd. Nogle Discussion Service-brugere kritiserer implementeringen af linked lists' 'addBefore()'- og 'addAfter()'-metoder, mens andre er uenige. Discussion Service-brugere anbefaler yderligere ressourcer, kritiserer datastrukturens effektivitet og fremh\xe6ver ressourcev\xe6rdien for l\xe6ringsalgoritmer.\""]}),"\n",(0,i.jsx)(r.h2,{id:"spacex-n\xe6rmer-sig-den-f\xf8rste-opsendelse-af-starship-super-heavy",children:"SpaceX n\xe6rmer sig den f\xf8rste opsendelse af Starship Super Heavy"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"Original"}),".\nSpaceX planl\xe6gger den f\xf8rste opsendelse af Starship-k\xf8ret\xf8jet i fuld skala senere i april, under foruds\xe6tning af myndighedsgodkendelse; Federal Aviation Administration har et hak for en opsendelsesdato den 17. april, med backup-datoer 18. til 21. april, i sit Operation Plan Advisory-dokument; Starship er blevet fuldt stablet p\xe5 platformen p\xe5 Starbase-anl\xe6gget i Boca Chica, Texas, og selskabet planl\xe6gger en opsendelsespr\xf8ve i n\xe6ste uge efterfulgt af den f\xf8rste integrerede flyvetest ca. en uge senere; det er uklart, om Starship vil komme i kredsl\xf8b og derefter straks udf\xf8re en deorbit-br\xe6nding for at spr\xf8jte ned, eller om der er tale om en lang suborbital flyvning."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX n\xe6rmer sig opsendelse af Starship Super Heavy, med kommentarer, der understreger dens betydning for kommerciel og milit\xe6r rumfart og et skift i tankegang. Offentlige kontrakter udg\xf8r mindst 80 % af SpaceX's indt\xe6gter. Starships kryogene raketter med flydende br\xe6ndstof kan anvendes til afskr\xe6kkende missioner. Finansiering af opsendelser er ikke udelukkende afh\xe6ngig af NASA. Video, der sammenligner raketst\xf8rrelser, f\xe5r opm\xe6rksomhed. SpaceX sigter forel\xf8big p\xe5 opsendelse den 20/4. FAA overvejer sikkerhedsproblemer. Blandede reaktioner p\xe5 Musks respektl\xf8se holdning."]}),"\n",(0,i.jsx)(r.h2,{id:"opbygning-af-musikalske-synthesizere-med-sql-foresp\xf8rgsler",children:"Opbygning af musikalske synthesizere med SQL-foresp\xf8rgsler"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Original"}),".\nEt GitHub-repositorium kaldet NoiSQL g\xf8r det muligt at generere musikalske lyde med SQL-foresp\xf8rgsler ved hj\xe6lp af grundl\xe6ggende b\xf8lger, oscillatorer, sequencere, LFO'er og st\xf8jgeneratorer. Oprettet i et 44,1kHz 16-bit stereo PCM-format med 16-bit stereo, kan brugerne styre signalerne ved at definere funktioner og udtryk i SQL. NoiSQL indeholder instruktioner og eksempler til at l\xe6re at bruge det. Projektet kan generere musikalske noter og rytmer med ClickHouse og kan oprette forskellige filformater. Selv om projektet har nogle begr\xe6nsninger, er det en innovativ m\xe5de at eksperimentere med ClickHouse's funktioner p\xe5, og det kan potentielt udvides til at omfatte videogenerering. Brugerne kan bidrage med nye eksempler til projektet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nEt projekt, der bygger synthesizere med SQL-foresp\xf8rgsler. Discussion Service-kommentatorer v\xe6rds\xe6tter den unikke id\xe9 og n\xe6vner lignende projekter. Nogle brugere bem\xe6rker den manglende forklaring og de potentielle s\xe5rbarheder i forbindelse med SQL-injektion."]}),"\n",(0,i.jsx)(r.h2,{id:"den-l\xe6ngste-lige-linje-i-storbritannien-uden-at-krydse-en-offentlig-vej",children:"Den l\xe6ngste lige linje i Storbritannien uden at krydse en offentlig vej"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Original"}),".\nDer er fundet en l\xe6ngere lige linje i Storbritannien uden at krydse en offentlig vej end den linje, som Ordnance Survey har identificeret i 2019. Den l\xe6ngste lige linje mellem veje i Storbritannien er ogs\xe5 den l\xe6ngste i hele Storbritannien. OS Open Roads-produktet leverer en masse gode \xe5bne data, men nogle gange omfatter det veje, der ikke er offentlige. Begr\xe6nsede lokale adgangsveje er normalt ubef\xe6stede private stier. Den l\xe6ngste linje i Storbritannien ligger vest for A9 i stedet for \xf8st for A9. Selv om kortl\xe6gningsdata er nyttige, skal de tages med et gran salt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nDen l\xe6ngste lige linje i Storbritannien er opdaget; den er m\xe5ske ikke helt lige. En vis diskussion om afstand fra veje, adgang til grusveje og befolkningstal. Brugere n\xe6vner fjerntliggende omr\xe5der rundt om i verden og muligheden for at automatisere s\xf8gningen. En diskussion om Schengen-aftalen og passtatistik."]}),"\n",(0,i.jsx)(r.h2,{id:"flipper-zero-forbudt-af-amazon-for-at-v\xe6re-en-card-skimming-device",children:'Flipper Zero forbudt af Amazon for at v\xe6re en "card skimming device'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"Original"}),'.\nAmazon har forbudt salget af Flipper Zero p\xe5 sin platform og beskylder den for at v\xe6re en "card skimming device". Enheden er et kompakt, b\xe6rbart og programmerbart v\xe6rkt\xf8j, der kan hj\xe6lpe med at eksperimentere med og debugge forskellige digitale og hardware-enheder. Brugere har fremvist dens muligheder, hvilket har stimuleret Amazons forbud. Nogle links til tidligere tilg\xe6ngelige Amazon-sider, der s\xe6lger Flipper Zero v\xe6rkt\xf8jet, er d\xf8de, mens andre angiver det som "ikke tilg\xe6ngeligt". Det brasilianske nationale telekommunikationsagentur har ogs\xe5 beslaglagt indg\xe5ende Flipper Zero-k\xf8b p\xe5 grund af dets p\xe5st\xe5ede brug af kriminelle. Du kan stadig k\xf8be Flipper Zero fra producentens officielle butik.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon forbyder k\xf8b af Flipper Zero, da den anses for at v\xe6re en kortskimming-enhed, men enheden kan k\xf8bes fra den officielle butik. K\xf8berne finder den interessant, men ikke brugbar. Lockpick-forbudspolitik er inkonsekvent og udokumenteret. Producenterne af Flipper Zero bruger et amerikansk baseret firma til betalinger, hvilket giver anledning til sikkerhedsproblemer. Amazon's motivation er tvivl om at undg\xe5 overskrifter, der forbinder dem med kriminalitet. Flipper Zero er forbudt p\xe5 grund af dets potentiale for ulovlige aktiviteter, men nogle h\xe6vder, at der er uoverensstemmelse med Amazons politikker. Nogle ser et potentiale for, at Amazon kan udvikle sin egen kopi-version. Flipper Zero er fjernet fra Amazon og eBay, men kan stadig k\xf8bes via det officielle websted."]}),"\n",(0,i.jsx)(r.h2,{id:"reverse-engineering-af-facebook-messenger-apiet",children:"Reverse Engineering af Facebook Messenger API'et"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Original"}),".\nForfatteren har reverse-engineered Facebook Messenger API'et for at skabe Messyger, et kommandolinjeprogram. Indl\xe6gget forklarer login-processen og cookies og tilbyder Python-kode p\xe5 GitHub. Der l\xe6gges v\xe6gt p\xe5 etisk adf\xe6rd, og der gives tips til at foretage anmodninger uden for browseren."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),'.\nUdviklere h\xe6vder oppustet og ineffektivt Messenger API. Facebook apps-bibliotek har JNI-bindinger. Behov for tredjepartsklienter, Digital Markets Act citeres. Bekymringer for spam og datah\xf8st, delte reverse engineering-v\xe6rkt\xf8jer. Profitmotiver er drivkraften bag reduktion af spam, nogle st\xf8tter statslig indgriben. Reguleringen b\xf8r fokusere p\xe5 cloud-udbydere, ikke p\xe5 "walled gardens". Bruger s\xe6tter sp\xf8rgsm\xe5lstegn ved begrebet ejendom og virksomheders kautioner.']}),"\n",(0,i.jsx)(r.h2,{id:"tatjana-van-varks-maskiner",children:"Tatjana van Varks maskiner"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"Original"}),".\nTatjana van Vark, en uafh\xe6ngig forsker fra Nederlandene, har bygget, kopieret og restaureret en lang r\xe6kke videnskabelige instrumenter. Hendes kunstf\xe6rdige projekter udviser fremragende h\xe5ndv\xe6rk og sans for detaljen, ofte med kompleksiteter, der g\xe5r ud over overfladiske udseende. Tatjanas arbejde har f\xf8rt hende ind i mange videnskabelige omr\xe5der, idet hun har bygget instrumenter inden for elektronik, optik, kryptologi, organisk kemi og meget mere. P\xe5 trods af hendes autodidakte maskinarbejderf\xe6rdigheder indeholder hendes v\xe6rksted maskiner af h\xf8j kvalitet, der kan klare kravene til hendes pr\xe6cisionsarbejde. Hendes arbejde er videnskabeligt h\xe5ndv\xe6rk p\xe5 h\xf8jeste niveau, og der findes imponerende fotoudstillinger p\xe5 hendes websted."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nTatjana van Varks arbejde er utroligt, og hun er en ekstrem hacker, der konstruerer instrumenter fra bunden. Hun har en bred vifte af f\xe6rdigheder og har produceret mange v\xe6rker, som det ville tage et helt liv at gennemg\xe5. Der er bekymring for, at der bliver f\xe6rre og f\xe6rre eksperter, da teknologien udvikler sig hurtigere, end vi kan l\xe6re den. Tatjana van Vark og h\xe5ndv\xe6rkere som hende har aldrig v\xe6ret almindelige."]}),"\n",(0,i.jsx)(r.h2,{id:"big-ball-of-mud-1999",children:"Big Ball of Mud (1999)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://www.laputan.org/mud/",children:"Original"}),".\nArtiklen unders\xf8ger BIG BALL OF MUD softwarearkitekturen og hvorfor den forts\xe6tter p\xe5 trods af h\xf8jt t\xe6nkende tilgange. Syv m\xf8nstre diskuteres, herunder smidekode og stykvis v\xe6kst, og \xe5rsagerne bag dem, s\xe5som tidsbegr\xe6nsninger og fors\xf8mmelse af arkitekturen. For tidlig arkitektur kan hindre udviklingen, og uerfarenhed eller udskiftning af medarbejdere kan begr\xe6nse sofistikeringen. Parprogrammering og kodegennemgang anbefales til \xf8jeblikkelig kontrol, mens refaktorering, reparation og konsolidering er afg\xf8rende for at bek\xe6mpe BIG BALL OF MUD. Der l\xe6gges v\xe6gt p\xe5 vigtigheden af inkrementel v\xe6kst, vedligeholdelse, tilpasning og streng testning. Det kan v\xe6re n\xf8dvendigt at genopbygge et system, men refactoring kan v\xe6re et alternativ ved at samle arkitektoniske elementer fra det nuv\xe6rende system."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),'.\nArtiklen "Big Ball of Mud (1999)" er et velanset v\xe6rk om softwareudvikling. Flere brugere roser dens indsigt og relevans og n\xe6vner den som en omfattende forklaring p\xe5, hvad man ser i virkelige situationer hver uge. Andre peger p\xe5 andre artikler af lignende betydning eller senere udviklinger inden for software engineering, f.eks. microservices. Nogle brugere kommenterer deres personlige erfaringer i forbindelse med artiklen. Endelig kritiserer nogle brugere artiklens formatering eller bem\xe6rker, at den tidligere er blevet offentliggjort.']}),"\n",(0,i.jsx)(r.h2,{id:"yann-lecun-og-andrew-ng-why-the-6-month-ai-pause-is-a-bad-idea-video",children:"Yann LeCun og Andrew Ng: Why the 6-Month AI Pause Is a Bad Idea [video]"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Original"}),".\nDette er ikke det egentlige indhold af artiklen. Giv venligst teksten, s\xe5 jeg kan opsummere den."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun og Andrew Ng kritiserer den 6-m\xe5neders AI-pause, idet de antyder, at den er urealistisk og giver OpenAI en fordel. Debatter om AI-vinter, menneskelig tankerepr\xe6sentation og samfundsm\xe6ssig forstyrrelse fremh\xe6ves. AI-fremskridt tilbyder uventede evner ud over tekst og giver udtryk for bekymringer om tab af arbejdspladser og fattigdom. Eksperter har blandede holdninger til effektiviteten af pausen for AI-udvikling og risiciene ved ureguleret AI. Den potentielle trussel fra AGI, der overg\xe5r den menneskelige intelligens, og overv\xe5gningsteknologier med dybdeindl\xe6ring tages op, sammen med bekymringer om AI's tilpasning til menneskelige m\xe5l."]}),"\n",(0,i.jsx)(r.h2,{id:"nsa-oprettede-online-cybersikkerhedskursus-med-100-vis-af-klasser",children:"NSA oprettede online cybersikkerhedskursus med 100-vis af klasser"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://clark.center/c/nccp",children:"Original"}),".\nNSA har oprettet et online cybersikkerhedskursus med hundredvis af klasser til r\xe5dighed. Kurset, der kaldes CLARK, d\xe6kker en lang r\xe6kke emner, herunder netv\xe6rkssikkerhed, kryptografi og cybertrusler. Kurserne henvender sig b\xe5de til begyndere og eksperter og er gratis tilg\xe6ngelige for alle med en internetforbindelse. Der har v\xe6ret en del kontroverser omkring kurset, idet nogle kritikere h\xe6vder, at det giver NSA en bagd\xf8r til at f\xe5 adgang til private oplysninger. NSA har imidlertid afvist disse p\xe5stande og erkl\xe6rer, at kurset udelukkende er et uddannelseskursus."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nNSA har oprettet et kursus i cybersikkerhed, men der er bekymring omkring agenturets brug af 0day exploits i offensive operationer. Nogle brugere bem\xe6rker, at opdelingen mellem offensiv og defensiv er mindre ildevarslende, end det ser ud til. Kurset er en del af CLARK-systemet, som delvist er finansieret af NSA, men som prim\xe6rt drives af Towson University. Nogle brugere kritiserer den manglende d\xe6kning af visse emner i kurset."]}),"\n",(0,i.jsx)(r.h2,{id:"erstatning-af-d\xe5rlige-systemer-med-d\xe5rlige-systemer",children:"Erstatning af d\xe5rlige systemer med d\xe5rlige systemer"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Original"}),".\nI sit blogindl\xe6g bruger Seth metaforen med for\xe6ldede parkeringsm\xe5lere til at illustrere behovet for at nyt\xe6nke og forbedre d\xe5rlige systemer. Selv om det kan virke dyrt at udskifte dem, har centraliserede systemer som Parkmobile-appen ofte deres egne mangler. Hvis vi vender tilbage til det oprindelige m\xe5l om at generere indt\xe6gter og forhindre parkering hele dagen, foresl\xe5r Seth at implementere en gratis app, der scanner en kode for at tillade en periode med parkeringstid. Andre muligheder for at \xf8ge indt\xe6gterne omfatter en online betalingstjeneste eller salg af parkeringskort med forskellige rabatmuligheder. Selv om det er sv\xe6rt at tr\xe6ffe UX-valg for et offentligt system, har distribuerede systemer som WordPress blomstret p\xe5 grund af deres decentrale og brugervenlige design. Den vigtigste fordel ved distribuerede systemer er deres evne til at forbedre sig over tid, i stedet for at forkalkes som centraliserede systemer. For at komme videre foresl\xe5r Seth, at vi prioriterer bedre l\xf8sninger i stedet for flere l\xf8sninger."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nEt enklere parkeringssystem i Danmark har manuelle urskiver med b\xf8der for snydere. Brugerne peger p\xe5 lignende systemer i udlandet. Der anvendes ofte komplekse l\xf8sninger p\xe5 trods af enkle muligheder. Parkeringsautomater i Chicago genererede 200 mio. dollars p\xe5 10 \xe5r. Nye elektroniske parkeringsm\xe5lere er mindre bekvemme end de klassiske. Regeringerne k\xe6mper med betalingssystemer og overlader det undertiden til s\xe6lgerne. Parkeringsautomater bruges prim\xe6rt til penge, men de forhindrer ogs\xe5 parkering hele dagen. Artiklen havde ingen pointe if\xf8lge en kommentator, mens en anden kritiserer forfatteren."]}),"\n",(0,i.jsx)(r.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Original"}),'.\nNeovim version 0.9.0 er blevet udgivet, med \xe6ndringer til iconv, libintl, optional params, lua2dox, semantiske tokens, \'+tui\', underst\xf8ttelse af Yarn node-moduler og fremh\xe6vning af kodeblokke. Vim version 8.2.2902 er ogs\xe5 blevet udgivet med fejlrettelser og forbedret Lua-scripting og LSP-underst\xf8ttelse. Neovims seneste version pr\xe6senterer sp\xe6ndende nye funktioner og stabilitetsforbedringer, mens Vim fokuserer p\xe5 fejlrettelser og forbedret funktionalitet. Neovims opdateringer omfatter forbedringer til "treesitter", "tui" og "windows", fra softwarel\xf8sninger til forbedret dokumentation, hvilket str\xf8mliner Neovim-oplevelsen og bef\xe6ster dets position som kompetent og brugervenlig. Andre opdateringer omfatter \xe6ndringer til funktionen \'expect_unchanged()\', EditorConfig og syntaksmarkering for hj\xe6lpefiler, en hovedl\xf8s instans, forbedrede LSP-klientfunktioner og plugin-underst\xf8ttelse for GUI\'er.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 oph\xe6ver for\xe6ldelse af 'exrc' og tilf\xf8jer en \"trust database\". Eksperter anbefaler appImage eller .local til installation. EditorConfig-underst\xf8ttelse er nu indbygget. Debat om Neovims fordele, mens nogle kritiserer fragmentering, foresl\xe5r andre plugin managers. Neovim giver mulighed for nye v\xe6rkt\xf8jer og plugins. Lua har fordele for udvikling af plugin. Helix Editor har objekt-verb-model, zero config sprogserver og en tutor. Dens valg er mindre fleksibelt, men brugerne er begejstrede for brugervenlighed og effektivitet."]}),"\n",(0,i.jsx)(r.h2,{id:"sp\xf8rg-hvad-er-din-bedste-ressource-til-at-holde-dig-ajour-med-udviklingen-inden-for-ai",children:"Sp\xf8rg Hvad er din bedste ressource til at holde dig ajour med udviklingen inden for AI?"}),"\n",(0,i.jsx)(r.p,{children:"N/A (Da dette blot er en generel vejledning til opsummering, er der ingen tekst at opsummere)."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nDiscussion Service-brugere anbefaler ressourcer til at holde sig ajour med udviklingen inden for AI, herunder Papers with Code-webstedet, blogs og nyhedsbreve. Forsigtighed tilr\xe5des p\xe5 grund af informationsoverbelastning. Nogle tilbyder ressourcer til begyndere. De seneste fremskridt inden for AI, herunder hardware og algoritmiske innovationer, har forbedret tr\xe6ningen af store neurale netv\xe6rk og har f\xf8rt til ydeevne p\xe5 menneskeligt niveau. Debatten forts\xe6tter om revolutionerende gennembrud."]}),"\n",(0,i.jsx)(r.h2,{id:"direkte-beviser-for-brugen-af-flere-stoffer-i-bronzealderen-fra-test-af-menneskeh\xe5r",children:"Direkte beviser for brugen af flere stoffer i bronzealderen fra test af menneskeh\xe5r"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nEn unders\xf8gelse har fundet direkte beviser for flere psykoaktive plantearter i bronzealderens Menorca ved hj\xe6lp af analyse af menneskeh\xe5r. H\xe5ret indeholdt efedrin, atropin og scopolamin. Ark\xe6ologer udleder normalt brugen af bevidsthedsforstyrrende stoffer fra artefakter, men denne analyse er direkte. Denne opdagelse kaster nyt lys over brugen af stoffer i oldtidens samfund og tyder p\xe5 specialiseret viden og mulig shamanistisk brug. Unders\xf8gelsen afsl\xf8rer vigtigheden af at forst\xe5 tidligere kulturers rolle i forbindelse med psykoaktive planter og brug af stoffer. Flere unders\xf8gelser viser beviser for brugen af psykoaktive planter i gamle kulturer, hvilket fremh\xe6ver den lange historie med menneskelig brug af narkotika."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nH\xe5rtests afsl\xf8rer stoffer i bronzealderen med flere psykoaktive arter. Kommentarer omhandler de samfundsm\xe6ssige konsekvenser af stofbrug, personlige valg, uddannelse og v\xe6rdier. Narkotikaforbud med rod i folkesundhed, moral og racisme. Neutral artikel, der undg\xe5r politiske fordomme og spekulationer."]}),"\n",(0,i.jsx)(r.h2,{id:"nypd-officerer-praler-med-at-malke-overtid-i-utilsigtet-optagelse",children:"NYPD-officerer praler med at malke overtid i utilsigtet optagelse"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"Original"}),'.\nEn tilf\xe6ldig optagelse, der blev foretaget under anholdelsen af en bygningsarbejder, har afsl\xf8ret politibetjente, der praler med at "malke overarbejde" og bruger neds\xe6ttende ord over for anholdte. Optagelsen kaster lys over, hvordan de seneste strafferetlige reformer har p\xe5virket den m\xe5de, hvorp\xe5 betjente behandler anholdelser og opkr\xe6ver overarbejde. Politibetjente skulle efter sigende udnytte \xe6ndringerne i lovene om kaution og bevisoptagelse til at optjene ekstra overarbejde. NYPD har afvist at kommentere optagelsen, som ogs\xe5 indeholder uf\xf8lsomme kommentarer fra betjente om tilbageholdte.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nNYPD-betjente praler med at malke overarbejde, men artiklen afsl\xf8rer deres brug af sk\xe6ldsord, vittigheder om institutionalisering af folk osv. Nogle mener, at retsh\xe5ndh\xe6velsen i USA har langt v\xe6rre problemer, og at politiets overarbejde er en afledningsman\xf8vre. Andre siger, at det er forfatningsstridigt at udnytte overarbejde ved at forl\xe6nge tilbageholdelsen og at det fortjener en sigtelse for forbrydelse. Korruptionen i politiet har f\xf8rt til krav om afskaffelse og udskiftning af politiet. Manglen p\xe5 passende tilsyn og kontrol g\xf8r det muligt at udnytte overarbejde og misligholdelse. Der er bekymring over den adf\xe6rd, som personer, der har f\xe5et v\xe5ben og en pr\xe6ferencebehandling i henhold til loven, udviser."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-chatgdb---gpt-drevet-gdb-assistent",children:"Vis ChatGDB - GPT-drevet GDB-assistent"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/pgosar/ChatGDB",children:"Original"}),".\nChatGDB er et v\xe6rkt\xf8j, der forbedrer debugging-oplevelsen i GDB ved at bruge kraften i ChatGPT, s\xe5 kommandoer i naturligt sprog kan udf\xf8res automatisk. Brugere kan ogs\xe5 bede ChatGPT om at forklare den kommando, der lige er blevet k\xf8rt, eller endda stille den et sp\xf8rgsm\xe5l. For at installere skal Python version 3.3 eller nyere og pip installeres, efterfulgt af kommandoen ",(0,i.jsx)(r.code,{children:"pip3 install chatgdb"})," og oprettelse af en eksekverbar fil med ",(0,i.jsx)(r.code,{children:"chatgdb -k <API KEY>"}),". V\xe6rkt\xf8jet kan bruges i GDB ved at skrive ",(0,i.jsx)(r.code,{children:"chat"})," efterfulgt af den \xf8nskede kommando, og kommandoen ",(0,i.jsx)(r.code,{children:"explain"})," kan bruges til at anmode om en forklaring p\xe5 den foreg\xe5ende kommando eller til at stille et sp\xf8rgsm\xe5l."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),".\nChatGDB er en GPT-drevet GDB-assistent, der forbedrer debugging-arbejdsgange. Discussion Service-brugeren bem\xe6rker programmets minimale kode. ChatGPT fremskynder brugerens forst\xe5else for ukendt teknologi, refaktoriseringsopgaver. CLI-version af ChatGPT foresl\xe5et. ChatGPT fremskynder arbejdsgange, p\xe5 trods af nogle brugeres pr\xe6ference for muskelhukommelse. ChatGPT-3 pr\xe6senterer naturlig sprogprompt til GDB, hvilket er nyttigt i forbindelse med ",(0,i.jsx)(r.code,{children:"memory leaks and segmentation faults."})," Gr\xe6nsefladen er stadig uh\xe5ndterbar i visse scenarier, mens skrifttype og farveskema er godt modtaget."]})]})}function k(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);